import 'dart:io';\nimport 'dart:typed_data';\n\nimport 'package:flutter/services.dart';\nimport 'package:pdf/pdf.dart';\nimport 'package:pdf/widgets.dart' as pw;\nimport 'package:printing/printing.dart';\n\nimport '../../data/models/service_card.dart';\nimport 'pdf_file_manager.dart';\n\nenum CardTemplate {\n  classic('classic', 'الكلاسيكي'),\n  modern('modern', 'العصري'),\n  minimal('minimal', 'البسيط'),\n  premium('premium', 'المميز');\n\n  const CardTemplate(this.code, this.displayName);\n  final String code;\n  final String displayName;\n}\n\nclass CardPdfGeneratorEnhanced {\n  static Future<Uint8List> generateCardsPdf(\n    List<ServiceCard> cards, {\n    CardTemplate template = CardTemplate.classic,\n    String companyName = 'NUM',\n    String companyDescription = 'خدمات الإنترنت',\n    String contactNumber = '+967772339262',\n    String location = 'اليمن - صنعاء',\n    String? customSuffix,\n  }) async {\n    final pdf = pw.Document();\n\n    // تحميل الخط العربي\n    final arabicFont = await _loadArabicFont();\n\n    // تحميل شعار الشركة (إذا توفر)\n    final logoImage = await _loadLogo();\n\n    // تقسيم البطاقات إلى صفحات (4 بطاقات في الصفحة)\n    final cardsPerPage = 4;\n    final pages = <List<ServiceCard>>[];\n    for (int i = 0; i < cards.length; i += cardsPerPage) {\n      final end = (i + cardsPerPage < cards.length) ? i + cardsPerPage : cards.length;\n      pages.add(cards.sublist(i, end));\n    }\n\n    for (final pageCards in pages) {\n      pdf.addPage(\n        pw.MultiPage(\n          pageFormat: PdfPageFormat.a4,\n          margin: const pw.EdgeInsets.all(20),\n          textDirection: pw.TextDirection.rtl,\n          theme: pw.ThemeData.withFont(\n            base: arabicFont,\n            bold: arabicFont,\n          ),\n          build: (pw.Context context) {\n            return [\n              _buildPageHeader(\n                companyName: companyName,\n                description: companyDescription,\n                logo: logoImage,\n                font: arabicFont,\n                template: template,\n              ),\n              pw.SizedBox(height: 20),\n              _buildCardsGrid(pageCards, arabicFont, contactNumber, template),\n              pw.SizedBox(height: 20),\n              _buildPageFooter(font: arabicFont, location: location),\n            ];\n          },\n        ),\n      );\n    }\n\n    return pdf.save();\n  }\n\n  static Future<pw.Font> _loadArabicFont() async {\n    try {\n      final fontData = await rootBundle.load('reference_backend/cards/font/tajawal.ttf');\n      return pw.Font.ttf(fontData);\n    } catch (e) {\n      // إذا فشل تحميل الخط العربي، استخدم خط افتراضي\n      return await PdfGoogleFonts.notoSansArabicRegular();\n    }\n  }\n\n  static Future<pw.ImageProvider?> _loadLogo() async {\n    try {\n      final logoData = await rootBundle.load('reference_backend/cards/img/card_img.png');\n      return pw.MemoryImage(logoData.buffer.asUint8List());\n    } catch (e) {\n      return null;\n    }\n  }\n\n  static pw.Widget _buildPageHeader({\n    required String companyName,\n    required String description,\n    pw.ImageProvider? logo,\n    required pw.Font font,\n    CardTemplate template = CardTemplate.classic,\n  }) {\n    return pw.Container(\n      width: double.infinity,\n      padding: const pw.EdgeInsets.all(16),\n      decoration: pw.BoxDecoration(\n        color: _getTemplateHeaderColor(template),\n        borderRadius: pw.BorderRadius.circular(8),\n        gradient: template == CardTemplate.premium\n            ? pw.LinearGradient(\n                colors: [PdfColors.blue900, PdfColors.blue700],\n              )\n            : null,\n      ),\n      child: pw.Row(\n        mainAxisAlignment: pw.MainAxisAlignment.spaceBetween,\n        children: [\n          pw.Column(\n            crossAxisAlignment: pw.CrossAxisAlignment.start,\n            children: [\n              pw.Text(\n                companyName,\n                style: pw.TextStyle(\n                  font: font,\n                  fontSize: 24,\n                  fontWeight: pw.FontWeight.bold,\n                  color: PdfColors.white,\n                ),\n              ),\n              pw.Text(\n                description,\n                style: pw.TextStyle(\n                  font: font,\n                  fontSize: 14,\n                  color: PdfColors.white70,\n                ),\n              ),\n              pw.Text(\n                'قالب: ${template.displayName}',\n                style: pw.TextStyle(\n                  font: font,\n                  fontSize: 10,\n                  color: PdfColors.white60,\n                ),\n              ),\n            ],\n          ),\n          if (logo != null)\n            pw.Container(\n              width: 50,\n              height: 50,\n              decoration: pw.BoxDecoration(\n                color: PdfColors.white,\n                borderRadius: pw.BorderRadius.circular(25),\n              ),\n              child: pw.Center(\n                child: pw.Image(logo, width: 35, height: 35),\n              ),\n            ),\n        ],\n      ),\n    );\n  }\n\n  static pw.Widget _buildPageFooter({\n    required pw.Font font,\n    required String location,\n  }) {\n    return pw.Container(\n      width: double.infinity,\n      padding: const pw.EdgeInsets.all(12),\n      decoration: pw.BoxDecoration(\n        color: PdfColors.grey200,\n        borderRadius: pw.BorderRadius.circular(6),\n      ),\n      child: pw.Row(\n        mainAxisAlignment: pw.MainAxisAlignment.spaceBetween,\n        children: [\n          pw.Text(\n            'تم إنشاؤها بواسطة نظام NUM',\n            style: pw.TextStyle(\n              font: font,\n              fontSize: 10,\n              color: PdfColors.grey600,\n            ),\n          ),\n          pw.Text(\n            location,\n            style: pw.TextStyle(\n              font: font,\n              fontSize: 10,\n              color: PdfColors.grey600,\n            ),\n          ),\n          pw.Text(\n            'تاريخ الطباعة: ${DateTime.now().day}/${DateTime.now().month}/${DateTime.now().year}',\n            style: pw.TextStyle(\n              font: font,\n              fontSize: 10,\n              color: PdfColors.grey600,\n            ),\n          ),\n        ],\n      ),\n    );\n  }\n\n  static pw.Widget _buildCardsGrid(List<ServiceCard> cards, pw.Font font, String contactNumber, CardTemplate template) {\n    final rows = <pw.Widget>[];\n    \n    for (int i = 0; i < cards.length; i += 2) {\n      final rowCards = <pw.Widget>[];\n      \n      rowCards.add(pw.Expanded(\n        child: _buildSingleCard(cards[i], font, contactNumber, template),\n      ));\n      \n      rowCards.add(pw.SizedBox(width: 20));\n      \n      if (i + 1 < cards.length) {\n        rowCards.add(pw.Expanded(\n          child: _buildSingleCard(cards[i + 1], font, contactNumber, template),\n        ));\n      } else {\n        rowCards.add(pw.Expanded(child: pw.Container()));\n      }\n      \n      rows.add(pw.Row(children: rowCards));\n      if (i + 2 < cards.length) {\n        rows.add(pw.SizedBox(height: 20));\n      }\n    }\n    \n    return pw.Column(children: rows);\n  }\n\n  static pw.Widget _buildSingleCard(ServiceCard card, pw.Font font, String contactNumber, CardTemplate template) {\n    return pw.Container(\n      height: _getCardHeight(template),\n      decoration: pw.BoxDecoration(\n        border: pw.Border.all(color: PdfColors.grey300, width: 2),\n        borderRadius: pw.BorderRadius.circular(12),\n        boxShadow: template == CardTemplate.premium\n            ? [\n                pw.BoxShadow(\n                  color: PdfColors.grey400,\n                  offset: const pw.Offset(2, 2),\n                  blurRadius: 4,\n                ),\n              ]\n            : null,\n      ),\n      child: pw.Column(\n        children: [\n          // رأس البطاقة\n          _buildCardHeader(card, font, template),\n          \n          // محتوى البطاقة\n          pw.Expanded(\n            child: pw.Padding(\n              padding: const pw.EdgeInsets.all(12),\n              child: _buildCardContent(card, font, contactNumber, template),\n            ),\n          ),\n        ],\n      ),\n    );\n  }\n\n  static pw.Widget _buildCardHeader(ServiceCard card, pw.Font font, CardTemplate template) {\n    switch (template) {\n      case CardTemplate.modern:\n        return pw.Container(\n          width: double.infinity,\n          padding: const pw.EdgeInsets.all(12),\n          decoration: pw.BoxDecoration(\n            gradient: pw.LinearGradient(\n              colors: [PdfColors.teal600, PdfColors.cyan400],\n            ),\n            borderRadius: const pw.BorderRadius.only(\n              topLeft: pw.Radius.circular(10),\n              topRight: pw.Radius.circular(10),\n            ),\n          ),\n          child: pw.Row(\n            mainAxisAlignment: pw.MainAxisAlignment.spaceBetween,\n            children: [\n              pw.Text(\n                'NUM',\n                style: pw.TextStyle(\n                  font: font,\n                  fontSize: 18,\n                  fontWeight: pw.FontWeight.bold,\n                  color: PdfColors.white,\n                ),\n              ),\n              pw.Text(\n                'INTERNET',\n                style: pw.TextStyle(\n                  font: font,\n                  fontSize: 10,\n                  color: PdfColors.white70,\n                ),\n              ),\n            ],\n          ),\n        );\n        \n      case CardTemplate.minimal:\n        return pw.Container(\n          width: double.infinity,\n          padding: const pw.EdgeInsets.all(8),\n          decoration: const pw.BoxDecoration(\n            color: PdfColors.grey100,\n            borderRadius: pw.BorderRadius.only(\n              topLeft: pw.Radius.circular(10),\n              topRight: pw.Radius.circular(10),\n            ),\n          ),\n          child: pw.Text(\n            'NUM · بطاقة إنترنت',\n            style: pw.TextStyle(\n              font: font,\n              fontSize: 12,\n              color: PdfColors.grey800,\n            ),\n            textAlign: pw.TextAlign.center,\n          ),\n        );\n        \n      case CardTemplate.premium:\n        return pw.Container(\n          width: double.infinity,\n          padding: const pw.EdgeInsets.all(12),\n          decoration: pw.BoxDecoration(\n            gradient: pw.LinearGradient(\n              colors: [PdfColors.purple800, PdfColors.deepPurple600],\n            ),\n            borderRadius: const pw.BorderRadius.only(\n              topLeft: pw.Radius.circular(10),\n              topRight: pw.Radius.circular(10),\n            ),\n          ),\n          child: pw.Column(\n            children: [\n              pw.Text(\n                'NUM PREMIUM',\n                style: pw.TextStyle(\n                  font: font,\n                  fontSize: 16,\n                  fontWeight: pw.FontWeight.bold,\n                  color: PdfColors.white,\n                ),\n              ),\n              pw.Text(\n                'خدمة إنترنت متميزة',\n                style: pw.TextStyle(\n                  font: font,\n                  fontSize: 8,\n                  color: PdfColors.white70,\n                ),\n              ),\n            ],\n          ),\n        );\n        \n      default: // classic\n        return pw.Container(\n          width: double.infinity,\n          padding: const pw.EdgeInsets.all(12),\n          decoration: pw.BoxDecoration(\n            gradient: pw.LinearGradient(\n              colors: [PdfColors.blue800, PdfColors.blue600],\n            ),\n            borderRadius: const pw.BorderRadius.only(\n              topLeft: pw.Radius.circular(10),\n              topRight: pw.Radius.circular(10),\n            ),\n          ),\n          child: pw.Column(\n            children: [\n              pw.Text(\n                'NUM',\n                style: pw.TextStyle(\n                  font: font,\n                  fontSize: 18,\n                  fontWeight: pw.FontWeight.bold,\n                  color: PdfColors.white,\n                ),\n              ),\n              pw.Text(\n                'بطاقة إنترنت',\n                style: pw.TextStyle(\n                  font: font,\n                  fontSize: 10,\n                  color: PdfColors.white70,\n                ),\n              ),\n            ],\n          ),\n        );\n    }\n  }\n\n  static pw.Widget _buildCardContent(ServiceCard card, pw.Font font, String contactNumber, CardTemplate template) {\n    return pw.Column(\n      crossAxisAlignment: pw.CrossAxisAlignment.center,\n      children: [\n        // اسم البطاقة\n        pw.Text(\n          card.title,\n          style: pw.TextStyle(\n            font: font,\n            fontSize: 14,\n            fontWeight: pw.FontWeight.bold,\n            color: _getTemplateTextColor(template),\n          ),\n          textAlign: pw.TextAlign.center,\n        ),\n        \n        pw.SizedBox(height: 8),\n        \n        // معلومات البطاقة\n        pw.Row(\n          mainAxisAlignment: pw.MainAxisAlignment.spaceEvenly,\n          children: [\n            _buildInfoItem('السعة', card.quota, font, template),\n            _buildInfoItem('السعر', '${card.price.toStringAsFixed(0)} ر.س', font, template),\n          ],\n        ),\n        \n        pw.SizedBox(height: 8),\n        pw.Divider(color: PdfColors.grey300),\n        pw.SizedBox(height: 8),\n        \n        // بيانات الدخول\n        pw.Row(\n          mainAxisAlignment: pw.MainAxisAlignment.spaceEvenly,\n          children: [\n            _buildInfoItem('المستخدم', card.username ?? 'user${card.id}', font, template),\n            _buildInfoItem('المرور', card.password ?? 'pass${card.id}', font, template),\n          ],\n        ),\n        \n        pw.Spacer(),\n        \n        // QR Code\n        pw.Container(\n          width: template == CardTemplate.premium ? 80 : 60,\n          height: template == CardTemplate.premium ? 80 : 60,\n          padding: const pw.EdgeInsets.all(4),\n          decoration: pw.BoxDecoration(\n            border: pw.Border.all(color: PdfColors.grey300),\n            borderRadius: pw.BorderRadius.circular(6),\n          ),\n          child: pw.BarcodeWidget(\n            barcode: pw.Barcode.qrCode(),\n            data: _generateQRData(card),\n          ),\n        ),\n        \n        pw.SizedBox(height: 8),\n        \n        // رقم الاتصال\n        pw.Text(\n          contactNumber,\n          style: pw.TextStyle(\n            font: font,\n            fontSize: 8,\n            color: PdfColors.grey600,\n          ),\n        ),\n        \n        // رقم البطاقة\n        if (template == CardTemplate.premium)\n          pw.Text(\n            'رقم البطاقة: ${card.id}',\n            style: pw.TextStyle(\n              font: font,\n              fontSize: 7,\n              color: PdfColors.grey500,\n            ),\n          ),\n      ],\n    );\n  }\n\n  static pw.Widget _buildInfoItem(String label, String value, pw.Font font, CardTemplate template) {\n    return pw.Column(\n      children: [\n        pw.Text(\n          label,\n          style: pw.TextStyle(\n            font: font,\n            fontSize: 8,\n            color: PdfColors.grey600,\n          ),\n        ),\n        pw.SizedBox(height: 2),\n        pw.Text(\n          value,\n          style: pw.TextStyle(\n            font: font,\n            fontSize: 10,\n            fontWeight: pw.FontWeight.bold,\n            color: _getTemplateAccentColor(template),\n          ),\n        ),\n      ],\n    );\n  }\n\n  static String _generateQRData(ServiceCard card) {\n    return '''{\"id\":\"${card.id}\",\"title\":\"${card.title}\",\"username\":\"${card.username ?? 'user${card.id}'}\",\"password\":\"${card.password ?? 'pass${card.id}'}\",\"quota\":\"${card.quota}\",\"price\":${card.price}}''';\n  }\n\n  // دوال مساعدة للقوالب\n  static PdfColor _getTemplateHeaderColor(CardTemplate template) {\n    switch (template) {\n      case CardTemplate.modern:\n        return PdfColors.teal600;\n      case CardTemplate.minimal:\n        return PdfColors.grey100;\n      case CardTemplate.premium:\n        return PdfColors.purple800;\n      default:\n        return PdfColors.blue900;\n    }\n  }\n\n  static PdfColor _getTemplateTextColor(CardTemplate template) {\n    switch (template) {\n      case CardTemplate.modern:\n        return PdfColors.teal800;\n      case CardTemplate.minimal:\n        return PdfColors.grey800;\n      case CardTemplate.premium:\n        return PdfColors.purple800;\n      default:\n        return PdfColors.blue900;\n    }\n  }\n\n  static PdfColor _getTemplateAccentColor(CardTemplate template) {\n    switch (template) {\n      case CardTemplate.modern:\n        return PdfColors.cyan600;\n      case CardTemplate.minimal:\n        return PdfColors.grey700;\n      case CardTemplate.premium:\n        return PdfColors.deepPurple600;\n      default:\n        return PdfColors.blue800;\n    }\n  }\n\n  static double _getCardHeight(CardTemplate template) {\n    switch (template) {\n      case CardTemplate.premium:\n        return 300;\n      case CardTemplate.minimal:\n        return 260;\n      default:\n        return 280;\n    }\n  }\n\n  // دوال الطباعة والحفظ المحدثة\n  static Future<void> printCards(\n    List<ServiceCard> cards, {\n    CardTemplate template = CardTemplate.classic,\n    String? customSuffix,\n  }) async {\n    final pdfData = await generateCardsPdf(cards, template: template, customSuffix: customSuffix);\n    await Printing.layoutPdf(\n      onLayout: (PdfPageFormat format) async => pdfData,\n      name: 'NUM_Cards_${template.code}_${DateTime.now().millisecondsSinceEpoch}',\n    );\n  }\n\n  static Future<String> saveCardsPdf(\n    List<ServiceCard> cards, {\n    CardTemplate template = CardTemplate.classic,\n    String? customName,\n    String? suffix,\n  }) async {\n    final pdfData = await generateCardsPdf(cards, template: template, customSuffix: suffix);\n    \n    return await PdfFileManager.savePdfFile(\n      pdfData,\n      PdfTemplateType.cards,\n      customName: '${template.code}_$customName',\n      suffix: suffix,\n    );\n  }\n\n  static Future<void> shareCards(\n    List<ServiceCard> cards, {\n    CardTemplate template = CardTemplate.classic,\n    String? customSuffix,\n  }) async {\n    final pdfData = await generateCardsPdf(cards, template: template, customSuffix: customSuffix);\n    await Printing.sharePdf(\n      bytes: pdfData,\n      filename: 'NUM_Cards_${template.code}_${DateTime.now().millisecondsSinceEpoch}.pdf',\n    );\n  }\n\n  static Future<void> previewCards(\n    List<ServiceCard> cards, {\n    CardTemplate template = CardTemplate.classic,\n  }) async {\n    final pdfData = await generateCardsPdf(cards, template: template);\n    await Printing.layoutPdf(\n      onLayout: (PdfPageFormat format) async => pdfData,\n      name: 'NUM Cards Preview - ${template.displayName}',\n    );\n  }\n}"